for name in ['Glucose3', 'Glucose4', 'Minisat22', 'MinisatGH', 'Cadical153', 'Cadical195']:
    try:
        cls = getattr(__import__('pysat.solvers', fromlist=[name]), name)
        s = cls()
        try:
            s.add_atmost([-1, -2], 1)
            print(f"{name}: supports atmost")
        except NotImplementedError:
            print(f"{name}: does NOT support atmost")
        s.delete()
    except Exception as e:
        print(f"{name}: error {e}")

